<template><main style="max-width:420px;margin:120px auto;padding:16px"><div class="card" style="padding:24px"><h1>Create an Account</h1><input v-model="f.name" placeholder="Name" class="field" style="width:100%;padding:12px;margin:6px 0" /><input v-model="f.username" placeholder="Username" class="field" style="width:100%;padding:12px;margin:6px 0" /><input v-model="f.email" placeholder="Email" class="field" style="width:100%;padding:12px;margin:6px 0" /><input v-model="f.password" type="password" placeholder="Password" class="field" style="width:100%;padding:12px;margin:6px 0" /><input v-model="f.confirm" type="password" placeholder="Confirm Password" class="field" style="width:100%;padding:12px;margin:6px 0" /><input v-model="f.pin" placeholder="Vault PIN (4-6 digits)" class="field" style="width:100%;padding:12px;margin:6px 0" /><p v-if="err" style="color:#ff6b6b">{{err}}</p><button class="btn-primary" style="width:100%" @click="go">Create Account</button><p style="text-align:center"><RouterLink to="/login">Already have an account? Sign In</RouterLink></p></div></main></template>
<script setup lang="ts">import {ref} from 'vue'; import {useRouter} from 'vue-router'; import {useAuth} from '../stores/auth'; const f=ref({name:'',username:'',email:'',password:'',confirm:'',pin:''}); const err=ref(''); const auth=useAuth(); const router=useRouter(); async function go(){ if(f.value.password!==f.value.confirm){err.value='Passwords do not match';return} try{ await auth.createAccount(f.value); router.push('/vault') }catch(e:any){err.value=e.message} }</script>
